const LOGO='assets/logo.png';
const portal=document.body.dataset.portal||'student';
const money=v=>Number(v||0).toLocaleString('pt-BR',{style:'currency',currency:'BRL'});
const brDate=s=>{if(!s)return '-';const [y,m,d]=s.split('-');return `${d}/${m}/${y}`};
const initials=n=>(n||'MI').split(' ').filter(Boolean).slice(0,2).map(x=>x[0]).join('').toUpperCase();
const badge=s=>{const v=String(s);const c=['Pago','Concluído','Aprovado','Ativo','Regular','Enviado'].includes(v)?'green':['Atrasado','Bloqueado','Suspenso','Reprovado'].includes(v)?'red':['Pendente','Em análise','Parcial','Simulado'].includes(v)?'orange':['Respondido','Aberto'].includes(v)?'blue':'gray';return `<span class="badge ${c}">${v}</span>`};
const progress=p=>`<div class="progress"><span style="width:${Math.max(0,Math.min(100,p))}%"></span></div>`;
function toast(msg,type='success'){const el=document.createElement('div');el.className=`toast ${type}`;el.textContent=msg;document.body.appendChild(el);setTimeout(()=>el.remove(),3300)}
function modal(html,wide=false){const b=document.createElement('div');b.className='modal-backdrop';b.innerHTML=`<div class="modal ${wide?'wide':''}">${html}</div>`;b.onclick=e=>{if(e.target===b)b.remove()};document.body.appendChild(b);b.querySelector('.close-btn')?.addEventListener('click',()=>b.remove());return b}
function esc(s){return String(s??'').replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[m]))}
const session={token:sessionStorage.getItem('mi_token'),user:JSON.parse(sessionStorage.getItem('mi_user')||'null')};
const state={page:portal==='admin'?'admin-dashboard':'dashboard',user:session.user,students:[],payments:[],requests:[],settings:null,logs:[]};

const studentNav=[
 ['Principal',[['dashboard','VG','Visão Geral']]],
 ['Vida Acadêmica',[['academico','AC','Acadêmico'],['disciplinas','MD','Minhas Disciplinas'],['notas','NF','Notas e Frequências'],['historico','HE','Histórico Escolar'],['calendario','CA','Calendário Acadêmico']]],
 ['Serviços',[['financeiro','FN','Financeiro'],['requerimentos','RQ','Requerimentos'],['atendimento','AT','Atendimento'],['documentos','DC','Documentos'],['certidoes','CD','Certidões e Declarações'],['atividades','AA','Atividades Complementares']]],
 ['Comunicação',[['comunicados','CO','Comunicados e Avisos']]],
 ['Conta',[['carteira','CI','Carteira do Aluno'],['perfil','PF','Meu Perfil'],['seguranca','SG','Senha e Segurança']]]
];
const adminNav=[
 ['Gestão',[['admin-dashboard','DG','Dashboard Geral'],['alunos','AL','Alunos e Acessos'],['admin-financeiro','FI','Financeiro'],['notificacoes','NO','Notificações'],['admin-relatorios','RE','Relatórios']]],
 ['Operação',[['admin-academico','GA','Gestão Acadêmica'],['admin-comunicados','GC','Comunicados']]],
 ['Sistema',[['auditoria','AU','Auditoria e Segurança']]]
];
const meta={
 dashboard:['Visão Geral','Acompanhe sua vida acadêmica em um só lugar.'],academico:['Acadêmico','Disciplinas, progresso e informações do curso.'],disciplinas:['Minhas Disciplinas','Acompanhe conteúdo, carga horária e progresso.'],notas:['Notas e Frequências','Consulte notas, médias e frequência.'],historico:['Histórico Escolar','Consulte seu histórico acadêmico.'],calendario:['Calendário Acadêmico','Datas de provas, aulas e prazos.'],financeiro:['Financeiro','Consulte mensalidades, pagamentos e cobranças.'],requerimentos:['Requerimentos','Solicite serviços acadêmicos e acompanhe protocolos.'],atendimento:['Atendimento','Fale com os setores da instituição.'],documentos:['Documentos','Arquivos acadêmicos disponibilizados para você.'],certidoes:['Certidões e Declarações','Solicite documentos acadêmicos.'],atividades:['Atividades Complementares','Registre e acompanhe sua carga complementar.'],comunicados:['Comunicados e Avisos','Notícias e informações institucionais.'],carteira:['Carteira do Aluno','Identificação acadêmica digital.'],perfil:['Meu Perfil','Dados cadastrais do aluno.'],seguranca:['Senha e Segurança','Somente o aluno pode alterar a própria senha.'],
 'admin-dashboard':['Dashboard Administrativo','Visão consolidada de alunos, financeiro e inadimplência.'],alunos:['Alunos e Acessos','Cadastre alunos, defina mensalidades e controle o acesso ao portal.'],'admin-financeiro':['Financeiro Administrativo','Gerencie mensalidades, valores pagos e cobranças.'],notificacoes:['Notificações de Inadimplência','Configure avisos automáticos para a equipe responsável da faculdade.'],'admin-relatorios':['Relatórios','Indicadores financeiros e acadêmicos para gestão.'],'admin-academico':['Gestão Acadêmica','Estrutura para lançamento de notas, turmas e disciplinas.'],'admin-comunicados':['Comunicados','Publique avisos para alunos.'],auditoria:['Auditoria e Segurança','Controle de permissões, rastreabilidade e política de senhas.']
};

function renderLogin(){document.getElementById('app').innerHTML=`<div class="login-shell"><section class="login-hero"><div class="login-brand"><img src="${LOGO}" alt="Inova Cursos Técnicos"><h1>${portal==='admin'?'Gestão do Meu Inova':'Seu futuro começa aqui.'}</h1><p>${portal==='admin'?'Acesso exclusivo para secretaria, financeiro, coordenação e administradores autorizados.':'Portal acadêmico para acompanhar sua vida escolar, financeira e documental.'}</p></div></section><section class="login-panel"><form class="login-card" id="loginForm"><a class="back-link" href="index.html">Voltar à escolha de acesso</a><img class="logo-mini" src="${LOGO}" alt="Inova"><div class="portal-label">${portal==='admin'?'Portal Administrativo':'Portal do Aluno'}</div><h2>Entrar no Meu Inova</h2><p class="intro">${portal==='admin'?'Use sua credencial institucional.':'Use CPF, matrícula ou e-mail.'}</p><div class="field"><label>${portal==='admin'?'E-mail institucional':'CPF, matrícula ou e-mail'}</label><input id="loginUser" autocomplete="username" required></div><div class="field"><label>Senha</label><div class="password-wrap"><input id="loginPass" type="password" autocomplete="current-password" required><button type="button" class="show-pass" id="showPass">Mostrar</button></div></div><div class="login-options"><label><input type="checkbox" checked> Manter conectado</label><button type="button" class="link-btn" id="forgot">Esqueci minha senha</button></div><button class="primary-btn full" type="submit">Entrar</button><div class="login-demo"><b>Acesso protegido</b><br><span class="muted">O Portal do Aluno e o Portal Administrativo usam permissões diferentes. A senha do aluno não é exibida ao administrador.</span></div></form></section></div>`;
 const p=document.getElementById('loginPass');document.getElementById('showPass').onclick=()=>{p.type=p.type==='password'?'text':'password';document.getElementById('showPass').textContent=p.type==='password'?'Mostrar':'Ocultar'};
 document.getElementById('forgot').onclick=()=>forgotPassword();
 document.getElementById('loginForm').onsubmit=async e=>{e.preventDefault();try{const r=await API.login(portal,document.getElementById('loginUser').value.trim(),p.value);sessionStorage.setItem('mi_token',r.token);sessionStorage.setItem('mi_user',JSON.stringify(r.user));state.user=r.user;await boot();}catch(err){toast(err.message,'error')}};
}
async function forgotPassword(){const current=document.getElementById('loginUser')?.value?.trim()||'';const m=modal(`<div class="modal-head"><h3>Recuperar senha</h3><button class="close-btn">Fechar</button></div><p class="small muted">${portal==='student'?'O link de redefinição é enviado diretamente ao aluno. A equipe administrativa não visualiza nem escolhe a nova senha.':'Informe o e-mail institucional cadastrado.'}</p><div class="field"><label>E-mail, CPF ou matrícula</label><input id="forgotId" value="${esc(current)}"></div><div class="modal-actions"><button class="secondary-btn cancel">Cancelar</button><button class="primary-btn send">Enviar link</button></div>`);m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.send').onclick=async()=>{try{const r=await API.forgot(portal,m.querySelector('#forgotId').value.trim());m.remove();toast(r.message||'Solicitação enviada.','info')}catch(e){toast(e.message,'error')}}}

async function boot(){if(!state.user){renderLogin();return}try{if(portal==='student'){state.user=await API.getStudent(state.user.id||1);state.payments=await API.studentPayments(state.user.id||1);state.requests=await API.requests()}else{state.students=await API.listStudents();state.payments=await API.listPayments();state.settings=await API.settings();state.logs=await API.logs()}renderApp()}catch(e){toast(e.message,'error');logout()}}
function sidebar(){const nav=portal==='admin'?adminNav:studentNav;return `<aside class="sidebar" id="sidebar"><div class="sidebar-brand"><img src="${LOGO}" alt="Inova"></div><div class="portal-chip">${portal==='admin'?'ACESSO ADMINISTRATIVO':'ACESSO DO ALUNO'}</div>${nav.map(([s,items])=>`<div class="menu-section">${s}</div>${items.map(([id,code,label])=>`<button class="nav-item ${state.page===id?'active':''}" data-page="${id}"><span class="nav-code">${code}</span><span>${label}</span></button>`).join('')}`).join('')}<div class="sidebar-footer"><button class="nav-item" id="logout"><span class="nav-code">SA</span><span>Sair</span></button></div></aside>`}
function renderApp(){const [title,sub]=meta[state.page]||['Meu Inova',''];const role=portal==='admin'?'Administrador':'Aluno';document.getElementById('app').innerHTML=`<div class="app-shell">${sidebar()}<main class="main"><header class="topbar"><div class="top-left"><button class="mobile-menu" id="mobileMenu">Menu</button><span class="top-title">Meu Inova</span></div><div class="top-actions"><button class="top-action" onclick="${portal==='admin'?"go('notificacoes')":"go('comunicados')"}">${portal==='admin'?'Central de alertas':'Avisos'}</button><div class="profile-chip"><div class="avatar">${initials(state.user.name)}</div><div class="who"><b>${esc(state.user.name)}</b><span>${role}</span></div></div></div></header><section class="content"><div class="page-head"><div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions" id="pageActions"></div></div><div id="pageContent">${pageContent()}</div></section></main></div>`;document.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>go(b.dataset.page));document.getElementById('logout').onclick=logout;document.getElementById('mobileMenu').onclick=()=>document.getElementById('sidebar').classList.toggle('open');attachEvents()}
function go(p){state.page=p;renderApp();window.scrollTo({top:0,behavior:'smooth'})}window.go=go;
function logout(){sessionStorage.removeItem('mi_token');sessionStorage.removeItem('mi_user');state.user=null;renderLogin()}

function pageContent(){if(portal==='admin')return ({'admin-dashboard':adminDashboard,alunos:adminStudents,'admin-financeiro':adminFinance,notificacoes:adminNotifications,'admin-relatorios':adminReports,'admin-academico':adminAcademic,'admin-comunicados':adminCommunications,auditoria:adminAudit}[state.page]||adminDashboard)();return ({dashboard,academico,disciplinas,notas,historico,calendario,financeiro,requerimentos,atendimento,documentos,certidoes,atividades,comunicados,carteira,perfil,seguranca}[state.page]||dashboard)()}

function dashboard(){const open=state.payments.filter(p=>p.status!=='Pago').reduce((a,p)=>a+(p.amountDue-p.amountPaid),0);return `<div class="grid grid-4"><div class="card stat-card"><div class="stat-icon">MAT</div><div><div class="label">Matrícula</div><div class="value">Ativa</div><div class="sub">2026.2</div></div></div><div class="card stat-card orange"><div class="stat-icon">R$</div><div><div class="label">Saldo em aberto</div><div class="value">${money(open)}</div><div class="sub">Consulte o financeiro</div></div></div><div class="card stat-card green"><div class="stat-icon">FQ</div><div><div class="label">Frequência média</div><div class="value">92%</div><div class="sub">Acima do mínimo</div></div></div><div class="card stat-card"><div class="stat-icon">CH</div><div><div class="label">Atividades</div><div class="value">68h</div><div class="sub">de 100h obrigatórias</div></div></div></div><div class="grid grid-3" style="margin-top:16px"><div class="card span-2"><div class="card-head"><h3>Acompanhamento Acadêmico</h3><button class="action-link" onclick="go('disciplinas')">Ver disciplinas</button></div>${[['Matemática Aplicada',82],['Português Técnico',76],['Informática Básica',91],['Gestão de Pessoas',69]].map(x=>`<div class="list-row"><div class="list-main"><b>${x[0]}</b><span>Progresso da disciplina</span></div><div style="width:40%">${progress(x[1])}</div></div>`).join('')}</div><div class="card"><h3>Avisos importantes</h3><div class="notice"><h4>Renovação de matrícula 2026.2</h4><p>Prazo aberto até 18 de agosto.</p></div><div class="notice"><h4>Semana de avaliações</h4><p>Consulte o calendário atualizado.</p></div><div class="notice"><h4>Situação financeira</h4><p>Há cobrança com vencimento em agosto.</p></div></div></div>`}
function academico(){return `<div class="grid grid-3"><div class="card span-2"><h3>Disciplinas Matriculadas - 2º Semestre / 2026</h3><div class="table-wrap"><table class="table"><thead><tr><th>Disciplina</th><th>Professor</th><th>Status</th><th>Nota</th><th>Frequência</th></tr></thead><tbody>${[['Matemática Aplicada','Prof. Renato Alves','Em andamento','8,4','94%'],['Português Técnico','Profa. Paula Mendes','Em andamento','7,8','91%'],['Informática Básica','Prof. André Ribeiro','Em andamento','9,1','96%'],['Gestão de Pessoas','Profa. Carla Rocha','Em andamento','8,0','88%']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${badge(x[2])}</td><td>${x[3]}</td><td>${x[4]}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h3>Calendário Acadêmico</h3><div class="timeline"><div class="timeline-item"><b>18 AGO</b><p>Renovação de matrícula</p></div><div class="timeline-item"><b>20 AGO</b><p>Avaliação de Matemática</p></div><div class="timeline-item"><b>31 AGO</b><p>Atividades complementares</p></div></div></div></div>`}
function disciplinas(){return `<div class="grid grid-3">${[['Matemática Aplicada','Renato Alves',82,80],['Português Técnico','Paula Mendes',76,60],['Informática Básica','André Ribeiro',91,80],['Gestão de Pessoas','Carla Rocha',69,60],['Empreendedorismo','Juliana Costa',55,40],['Ética Profissional','Marcos Silva',88,40]].map(x=>`<div class="card subject-card"><div class="card-head"><div><h4>${x[0]}</h4><p>Professor(a): ${x[1]}</p></div>${badge('Em andamento')}</div><div class="subject-meta"><span>Progresso</span><b>${x[2]}%</b></div>${progress(x[2])}<div class="subject-meta"><span>Carga horária</span><b>${x[3]}h</b></div><button class="secondary-btn full" onclick="toast('Conteúdo da disciplina aberto em modo demonstrativo.','info')">Abrir disciplina</button></div>`).join('')}</div>`}
function notas(){return `<div class="card"><div class="card-head"><h3>Notas e Frequências - 2026.2</h3><span class="badge blue">Média global 8,3</span></div><div class="table-wrap"><table class="table"><thead><tr><th>Disciplina</th><th>N1</th><th>N2</th><th>Trabalho</th><th>Média</th><th>Frequência</th><th>Situação</th></tr></thead><tbody>${[['Matemática Aplicada','8,0','8,5','9,0','8,5','94%','Aprovado'],['Português Técnico','7,5','8,0','8,5','8,0','91%','Aprovado'],['Informática Básica','9,0','9,0','9,5','9,2','96%','Aprovado'],['Gestão de Pessoas','7,0','8,0','8,0','7,7','88%','Aprovado']].map(x=>`<tr>${x.slice(0,6).map((v,i)=>`<td>${i===0?`<b>${v}</b>`:v}</td>`).join('')}<td>${badge(x[6])}</td></tr>`).join('')}</tbody></table></div></div>`}
function historico(){return `<div class="grid grid-3"><div class="card span-2"><div class="card-head"><h3>Histórico Escolar</h3><button class="secondary-btn" onclick="downloadText('historico_meu_inova.txt','Histórico escolar demonstrativo - Meu Inova')">Baixar</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Período</th><th>Disciplina</th><th>Carga horária</th><th>Média</th><th>Situação</th></tr></thead><tbody>${[['2026.1','Fundamentos de Administração','60h','8,7','Aprovado'],['2026.1','Comunicação Empresarial','40h','8,1','Aprovado'],['2026.1','Matemática Financeira','60h','7,9','Aprovado'],['2026.1','Informática Aplicada','80h','9,0','Aprovado']].map(x=>`<tr><td>${x[0]}</td><td><b>${x[1]}</b></td><td>${x[2]}</td><td>${x[3]}</td><td>${badge(x[4])}</td></tr>`).join('')}</tbody></table></div></div><div class="card"><h3>Resumo</h3><div class="metric"><span>Média global</span><b>8,3</b></div><div class="metric"><span>Carga cursada</span><b>920h</b></div><div class="metric"><span>Carga total</span><b>1.800h</b></div><div class="metric"><span>Situação</span>${badge('Ativo')}</div></div></div>`}
function calendario(){const days=Array.from({length:35},(_,i)=>i-3);return `<div class="card"><div class="card-head"><h3>Agosto de 2026</h3><span class="badge blue">Calendário acadêmico</span></div><div class="calendar-grid">${['DOM','SEG','TER','QUA','QUI','SEX','SÁB'].map(d=>`<div class="cal-name">${d}</div>`).join('')}${days.map(d=>{const n=d<=0?31+d:d;const ev=d===10?'<span class="event orange">Vencimento</span>':d===18?'<span class="event">Matrícula</span>':d===20?'<span class="event">Avaliação</span>':'';return `<div class="cal-day ${d===11?'today':''}" style="${d<=0||d>31?'opacity:.35':''}">${n}${ev}</div>`}).join('')}</div></div>`}
function financeiro(){const open=state.payments.filter(p=>p.status!=='Pago').reduce((a,p)=>a+(p.amountDue-p.amountPaid),0);const paid=state.payments.reduce((a,p)=>a+p.amountPaid,0);return `<div class="grid grid-4"><div class="card stat-card orange"><div class="stat-icon">AB</div><div><div class="label">Saldo em aberto</div><div class="value">${money(open)}</div><div class="sub">Valores ainda não quitados</div></div></div><div class="card stat-card green"><div class="stat-icon">PG</div><div><div class="label">Total pago</div><div class="value">${money(paid)}</div><div class="sub">Cobranças exibidas</div></div></div><div class="card stat-card"><div class="stat-icon">MN</div><div><div class="label">Mensalidade vigente</div><div class="value">${money(state.user.monthlyFee)}</div><div class="sub">Definida pela instituição</div></div></div><div class="card stat-card red"><div class="stat-icon">ST</div><div><div class="label">Situação</div><div class="value">${state.payments.some(p=>p.status==='Atrasado')?'Atenção':'Regular'}</div><div class="sub">Consulte as cobranças</div></div></div></div><div class="card" style="margin-top:16px"><h3>Boletos e Faturas</h3><div class="table-wrap"><table class="table"><thead><tr><th>Descrição</th><th>Vencimento</th><th>Valor</th><th>Pago</th><th>Status</th><th class="right">Ação</th></tr></thead><tbody>${state.payments.map(p=>`<tr><td><b>${esc(p.desc)}</b></td><td>${brDate(p.due)}</td><td>${money(p.amountDue)}</td><td>${money(p.amountPaid)}</td><td>${badge(p.status)}</td><td class="right">${p.status==='Pago'?'<button class="mini-btn">Recibo</button>':`<button class="mini-btn orange" onclick="studentPay('${p.id}')">Pagar</button>`}</td></tr>`).join('')}</tbody></table></div></div>`}
window.studentPay=id=>{const p=state.payments.find(x=>x.id===id);const remaining=p.amountDue-p.amountPaid;const m=modal(`<div class="modal-head"><h3>Pagamento - ${esc(p.desc)}</h3><button class="close-btn">Fechar</button></div><div class="kpi-strip" style="grid-template-columns:1fr 1fr"><div class="kpi"><small>Saldo</small><b>${money(remaining)}</b></div><div class="kpi"><small>Vencimento</small><b>${brDate(p.due)}</b></div></div><div class="divider"></div><div class="field"><label>Forma de pagamento</label><select><option>PIX</option><option>Cartão de crédito</option><option>Boleto</option></select></div><div class="alert-box">No protótipo local, o pagamento é simulado. Na versão integrada, a baixa deve ocorrer somente após confirmação do gateway de pagamento.</div><div class="modal-actions"><button class="secondary-btn cancel">Cancelar</button><button class="primary-btn confirm">Simular pagamento</button></div>`);m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.confirm').onclick=()=>{m.remove();toast('Pagamento simulado. A versão de produção aguardará confirmação real do gateway.','info')}};
function requerimentos(){return `<div class="card"><div class="card-head"><h3>Meus Requerimentos</h3><button class="primary-btn" id="newReq">Novo requerimento</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Protocolo</th><th>Solicitação</th><th>Data</th><th>Status</th></tr></thead><tbody>${state.requests.map(r=>`<tr><td><b>${r.id}</b></td><td>${esc(r.type)}</td><td>${r.date}</td><td>${badge(r.status)}</td></tr>`).join('')}</tbody></table></div></div>`}
function atendimento(){return `<div class="grid grid-3"><div class="card span-2"><div class="card-head"><h3>Meus atendimentos</h3><button class="primary-btn" onclick="toast('Atendimento aberto em modo demonstrativo.','info')">Novo atendimento</button></div>${[['#AT-523','Dúvida sobre emissão de certificado','Acadêmico','Respondido'],['#AT-517','Atualização cadastral','Secretaria','Em análise'],['#AT-496','Confirmação de pagamento','Financeiro','Concluído']].map(x=>`<div class="list-row"><div class="list-main"><b>${x[1]}</b><span>${x[0]} - ${x[2]}</span></div>${badge(x[3])}</div>`).join('')}</div><div class="card"><h3>Canais de atendimento</h3><div class="metric"><span>Central do Aluno</span><b>08h às 18h</b></div><div class="metric"><span>E-mail</span><b>atendimento@inovacursos.com.br</b></div><div class="metric"><span>Telefone</span><b>(65) 3000-0000</b></div></div></div>`}
function documentos(){return `<div class="card"><h3>Documentos disponíveis</h3><div class="table-wrap"><table class="table"><thead><tr><th>Documento</th><th>Categoria</th><th>Atualizado em</th><th class="right">Ação</th></tr></thead><tbody>${[['Manual do Aluno 2026','Institucional','01/08/2026'],['Regulamento Acadêmico','Acadêmico','20/07/2026'],['Calendário Acadêmico 2026.2','Acadêmico','15/07/2026'],['Guia de Estágio','Estágio','10/07/2026']].map(x=>`<tr><td><b>${x[0]}</b></td><td>${x[1]}</td><td>${x[2]}</td><td class="right"><button class="mini-btn" onclick="downloadText('${x[0].replaceAll(' ','_')}.txt','Documento demonstrativo: ${x[0]}')">Baixar</button></td></tr>`).join('')}</tbody></table></div></div>`}
function certidoes(){return `<div class="grid grid-3">${[['Declaração de Matrícula','Comprova vínculo ativo'],['Histórico Escolar','Registro de disciplinas'],['Atestado de Frequência','Comprova frequência'],['Certidão de Conclusão','Para alunos concluintes'],['Declaração Financeira','Situação de pagamentos'],['Ementa de Disciplina','Conteúdo programático']].map(x=>`<div class="card"><h3>${x[0]}</h3><p class="small muted">${x[1]}</p><button class="primary-btn full" onclick="toast('Solicitação registrada.','info')">Solicitar / Emitir</button></div>`).join('')}</div>`}
function atividades(){return `<div class="grid grid-4"><div class="card stat-card"><div class="stat-icon">CU</div><div><div class="label">Cursos</div><div class="value">28h</div></div></div><div class="card stat-card"><div class="stat-icon">EV</div><div><div class="label">Eventos</div><div class="value">20h</div></div></div><div class="card stat-card"><div class="stat-icon">PR</div><div><div class="label">Projetos</div><div class="value">20h</div></div></div><div class="card stat-card orange"><div class="stat-icon">TT</div><div><div class="label">Total validado</div><div class="value">68h</div><div class="sub">de 100h</div></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Atividades registradas</h3><button class="primary-btn" onclick="toast('Envio de atividade aberto em modo demonstrativo.','info')">Nova atividade</button></div>${[['Curso de Excel Avançado','20h','Aprovado'],['Semana Técnica Inova','12h','Aprovado'],['Palestra de Empreendedorismo','4h','Em análise']].map(x=>`<div class="list-row"><div class="list-main"><b>${x[0]}</b><span>${x[1]}</span></div>${badge(x[2])}</div>`).join('')}</div>`}
function comunicados(){return `<div class="grid grid-3"><div class="card span-2"><h3>Comunicados recentes</h3>${[['Importante','Renovação de matrícula 2026.2','O período de renovação está aberto até 18 de agosto.'],['Acadêmico','Calendário de avaliações atualizado','Confira as novas datas de provas e trabalhos.'],['Financeiro','Pagamento via PIX','O portal está preparado para integração com gateway de pagamento.'],['Evento','Semana Técnica Inova','Inscrições abertas para oficinas e palestras.']].map(x=>`<div class="notice"><h4>${x[0]} - ${x[1]}</h4><p>${x[2]}</p></div>`).join('')}</div><div class="card"><h3>Próximos prazos</h3><div class="timeline"><div class="timeline-item"><b>18 AGO</b><p>Renovação de matrícula</p></div><div class="timeline-item"><b>20 AGO</b><p>Entrega de trabalho</p></div><div class="timeline-item"><b>31 AGO</b><p>Atividades complementares</p></div></div></div></div>`}
function carteira(){const u=state.user;return `<div class="grid grid-2"><div class="student-card"><img class="brand" src="${LOGO}" alt="Inova"><div class="student-card-body"><div class="student-photo">${initials(u.name)}</div><div><h2>${esc(u.name)}</h2><p>Matrícula: ${u.registration}</p><p>Curso: ${esc(u.course)}</p><p>Período: ${esc(u.period)}</p><p>Validade: 31/12/2026</p><div class="barcode"></div></div></div></div><div class="card"><h3>Carteira Digital do Aluno</h3><p class="small muted">Identificação para comprovação de vínculo estudantil.</p><div class="metric"><span>Situação</span>${badge(u.access?'Ativo':'Suspenso')}</div><div class="metric"><span>Unidade</span><b>${esc(u.campus)}</b></div><div class="metric"><span>Validade</span><b>31/12/2026</b></div><button class="primary-btn full" style="margin-top:13px" onclick="window.print()">Imprimir carteira</button></div></div>`}
function perfil(){const u=state.user;return `<div class="grid grid-3"><div class="card"><div class="student-photo" style="margin:auto">${initials(u.name)}</div><h3 style="text-align:center;margin-top:12px">${esc(u.name)}</h3><p class="small muted" style="text-align:center">Matrícula ${u.registration}</p></div><div class="card span-2"><form id="profileForm"><div class="grid grid-2"><div class="field span-2"><label>Nome completo</label><input id="pfName" value="${esc(u.name)}"></div><div class="field"><label>E-mail</label><input id="pfEmail" value="${esc(u.email)}"></div><div class="field"><label>Telefone</label><input id="pfPhone" value="${esc(u.phone)}"></div><div class="field"><label>CPF</label><input value="${esc(u.cpf)}" disabled></div><div class="field"><label>Curso</label><input value="${esc(u.course)}" disabled></div></div><button class="primary-btn" type="submit">Salvar dados</button></form></div></div>`}
function seguranca(){return `<div class="grid grid-2"><div class="card"><h3>Alterar minha senha</h3><div class="security-note">A senha pertence ao aluno. O administrador pode suspender ou liberar o acesso e enviar um link de recuperação, mas não pode definir nem visualizar a senha do aluno.</div><form id="passwordForm" style="margin-top:15px"><div class="field"><label>Senha atual</label><input id="currentPass" type="password" required></div><div class="field"><label>Nova senha</label><input id="newPass" type="password" minlength="6" required></div><div class="field"><label>Confirmar nova senha</label><input id="confirmPass" type="password" minlength="6" required></div><button class="primary-btn" type="submit">Alterar senha</button></form></div><div class="card"><h3>Esqueci minha senha</h3><p class="small muted">A recuperação é feita por link temporário enviado ao e-mail cadastrado do próprio aluno.</p><button class="secondary-btn" id="selfReset">Enviar link de recuperação</button><div class="divider"></div><h3>Boas práticas</h3><p class="small muted">Use senha exclusiva, não compartilhe credenciais e encerre a sessão em computadores compartilhados.</p></div></div>`}

function adminStats(){const active=state.students.filter(s=>s.access).length;const overdue=state.payments.filter(p=>p.status==='Atrasado');const due=state.payments.reduce((a,p)=>a+p.amountDue,0),paid=state.payments.reduce((a,p)=>a+p.amountPaid,0);return {active,overdue:overdue.length,due,paid,rate:due?Math.round((paid/due)*100):0}}
function adminDashboard(){const s=adminStats();return `<div class="card admin-callout"><div class="card-head"><div><h3>Painel Administrativo</h3><p class="small muted">Acesso separado do portal do aluno, com permissões administrativas.</p></div><span class="badge orange">Administrador</span></div><div class="kpi-strip"><div class="kpi"><small>Alunos cadastrados</small><b>${state.students.length}</b></div><div class="kpi"><small>Acessos ativos</small><b>${s.active}</b></div><div class="kpi"><small>Total recebido</small><b>${money(s.paid)}</b></div><div class="kpi"><small>Cobranças atrasadas</small><b>${s.overdue}</b></div></div></div><div class="grid grid-3" style="margin-top:16px"><div class="card span-2"><div class="card-head"><h3>Inadimplência que exige atenção</h3><button class="action-link" onclick="go('notificacoes')">Configurar avisos</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Aluno</th><th>Mensalidade</th><th>Vencimento</th><th>Saldo</th><th>Status</th></tr></thead><tbody>${state.payments.filter(p=>p.status==='Atrasado').map(p=>{const st=state.students.find(s=>s.id===p.studentId);return `<tr><td><b>${esc(st?.name||'-')}</b></td><td>${money(p.amountDue)}</td><td>${brDate(p.due)}</td><td>${money(p.amountDue-p.amountPaid)}</td><td>${badge('Atrasado')}</td></tr>`}).join('')}</tbody></table></div></div><div class="card"><h3>Governança de acesso</h3><div class="metric"><span>Admin altera senha do aluno</span><b>Não permitido</b></div><div class="metric"><span>Admin suspende acesso</span><b>Permitido</b></div><div class="metric"><span>Admin define mensalidade</span><b>Permitido</b></div><div class="metric"><span>Aluno altera própria senha</span><b>Permitido</b></div></div><div class="card span-3"><div class="card-head"><h3>Recebimento no período</h3><span class="badge green">${s.rate}% recebido</span></div><div class="chart">${[62,72,68,80,76,90,84].map((h,i)=>`<div class="bar" style="height:${h}%"><span>${['Fev','Mar','Abr','Mai','Jun','Jul','Ago'][i]}</span></div>`).join('')}</div></div></div>`}
function adminStudents(){return `<div class="card"><div class="card-head"><h3>Gestão de Alunos e Acessos</h3><button class="primary-btn" id="newStudent">Cadastrar aluno</button></div><div class="filters"><input class="filter search" id="studentSearch" placeholder="Buscar por nome, matrícula ou e-mail"><button class="filter" id="onlyBlocked">Somente suspensos</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Aluno</th><th>Matrícula</th><th>Curso</th><th>Mensalidade</th><th>Acesso</th><th class="right">Ações</th></tr></thead><tbody id="studentRows">${studentRows(state.students)}</tbody></table></div></div>`}
function studentRows(list){return list.map(s=>`<tr><td><b>${esc(s.name)}</b><br><span class="muted">${esc(s.email)}</span></td><td>${s.registration}</td><td>${esc(s.course)}</td><td><b>${money(s.monthlyFee)}</b></td><td>${badge(s.access?'Ativo':'Suspenso')}</td><td class="right"><div class="table-actions"><button class="mini-btn" onclick="openStudent(${s.id})">Abrir</button><button class="mini-btn" onclick="resetStudentPassword(${s.id})">Enviar recuperação</button><button class="mini-btn ${s.access?'danger':'green'}" onclick="toggleAccess(${s.id},${!s.access})">${s.access?'Suspender':'Restaurar'}</button></div></td></tr>`).join('')}
window.openStudent=id=>{const s=state.students.find(x=>x.id===id);const pays=state.payments.filter(p=>p.studentId===id);const m=modal(`<div class="modal-head"><h3>${esc(s.name)} - ${s.registration}</h3><button class="close-btn">Fechar</button></div><div class="grid grid-2"><div class="field"><label>E-mail</label><input value="${esc(s.email)}" disabled></div><div class="field"><label>Acesso ao portal</label><input value="${s.access?'Ativo':'Suspenso'}" disabled></div><div class="field"><label>Mensalidade vigente</label><input id="fee" type="number" step="0.01" value="${s.monthlyFee}"></div><div class="field"><label>Curso</label><input id="course" value="${esc(s.course)}"></div></div><div class="security-note">O administrador pode ajustar a mensalidade e o acesso, mas não existe campo para trocar a senha do aluno. Em caso de esquecimento, use "Enviar recuperação".</div><div class="divider"></div><h3>Financeiro do aluno</h3><div class="table-wrap"><table class="table"><thead><tr><th>Cobrança</th><th>Vencimento</th><th>Valor</th><th>Pago</th><th>Status</th></tr></thead><tbody>${pays.map(p=>`<tr><td>${esc(p.desc)}</td><td>${brDate(p.due)}</td><td>${money(p.amountDue)}</td><td>${money(p.amountPaid)}</td><td>${badge(p.status)}</td></tr>`).join('')}</tbody></table></div><div class="modal-actions"><button class="secondary-btn close">Cancelar</button><button class="primary-btn save">Salvar alterações</button></div>` ,true);m.querySelector('.close').onclick=()=>m.remove();m.querySelector('.save').onclick=async()=>{try{await API.updateStudent(id,{monthlyFee:Number(m.querySelector('#fee').value),course:m.querySelector('#course').value});state.students=await API.listStudents();m.remove();toast('Cadastro atualizado.');renderApp()}catch(e){toast(e.message,'error')}}}
window.toggleAccess=async(id,access)=>{try{await API.setAccess(id,access);state.students=await API.listStudents();toast(access?'Acesso do aluno restaurado.':'Acesso do aluno suspenso.');renderApp()}catch(e){toast(e.message,'error')}};
window.resetStudentPassword=async id=>{try{const r=await API.sendPasswordReset(id);toast(r.message,'info')}catch(e){toast(e.message,'error')}};
function adminFinance(){const s=adminStats();return `<div class="grid grid-4"><div class="card stat-card"><div class="stat-icon">COB</div><div><div class="label">Total cobrado</div><div class="value">${money(s.due)}</div></div></div><div class="card stat-card green"><div class="stat-icon">REC</div><div><div class="label">Total recebido</div><div class="value">${money(s.paid)}</div></div></div><div class="card stat-card orange"><div class="stat-icon">AB</div><div><div class="label">Em aberto</div><div class="value">${money(s.due-s.paid)}</div></div></div><div class="card stat-card red"><div class="stat-icon">ATR</div><div><div class="label">Atrasadas</div><div class="value">${s.overdue}</div></div></div></div><div class="card" style="margin-top:16px"><div class="card-head"><h3>Cobranças e pagamentos</h3><button class="primary-btn" id="newCharge">Nova cobrança</button></div><div class="table-wrap"><table class="table"><thead><tr><th>Aluno</th><th>Descrição</th><th>Vencimento</th><th>Devido</th><th>Pago</th><th>Status</th><th class="right">Ação</th></tr></thead><tbody>${state.payments.map(p=>{const st=state.students.find(s=>s.id===p.studentId);return `<tr><td><b>${esc(st?.name||'-')}</b></td><td>${esc(p.desc)}</td><td>${brDate(p.due)}</td><td>${money(p.amountDue)}</td><td>${money(p.amountPaid)}</td><td>${badge(p.status)}</td><td class="right">${p.status==='Pago'?'<span class="muted">Quitado</span>':`<button class="mini-btn green" onclick="registerPayment('${p.id}')">Registrar pagamento</button>`}</td></tr>`}).join('')}</tbody></table></div></div>`}
window.registerPayment=id=>{const p=state.payments.find(x=>x.id===id),remaining=p.amountDue-p.amountPaid;const m=modal(`<div class="modal-head"><h3>Registrar valor pago</h3><button class="close-btn">Fechar</button></div><p class="small muted">O painel administrativo registra o valor efetivamente pago pelo aluno. Em integração com gateway, este registro pode ser automático por webhook.</p><div class="field"><label>Valor restante</label><input value="${money(remaining)}" disabled></div><div class="field"><label>Valor recebido agora</label><input id="paidAmount" type="number" step="0.01" max="${remaining}" value="${remaining}"></div><div class="modal-actions"><button class="secondary-btn cancel">Cancelar</button><button class="primary-btn confirm">Confirmar recebimento</button></div>`);m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.confirm').onclick=async()=>{try{await API.registerPayment(id,Number(m.querySelector('#paidAmount').value));state.payments=await API.listPayments();m.remove();toast('Pagamento registrado.');renderApp()}catch(e){toast(e.message,'error')}}}
function adminNotifications(){const s=state.settings||{};return `<div class="grid grid-3"><div class="card span-2"><div class="card-head"><div><h3>Canais automáticos</h3><p class="small muted">Avisos são enviados para os responsáveis da faculdade quando uma mensalidade fica atrasada.</p></div><button class="primary-btn" id="runCheck">Verificar atrasos agora</button></div><div class="channel-grid"><div class="channel-card"><label>E-mail <input class="switch" id="chEmail" type="checkbox" ${s.email?'checked':''}></label><p>Envia mensagem ao e-mail do setor financeiro ou secretaria.</p></div><div class="channel-card"><label>SMS <input class="switch" id="chSms" type="checkbox" ${s.sms?'checked':''}></label><p>Envia SMS para o telefone institucional configurado.</p></div><div class="channel-card"><label>WhatsApp <input class="switch" id="chWhatsapp" type="checkbox" ${s.whatsapp?'checked':''}></label><p>Envia mensagem via WhatsApp Business API ou provedor compatível.</p></div></div><div class="grid grid-2" style="margin-top:15px"><div class="field"><label>E-mails dos responsáveis (separados por vírgula)</label><input id="staffEmail" value="${esc(s.staffEmail||'')}"></div><div class="field"><label>Telefones institucionais com DDI (separados por vírgula)</label><input id="staffPhone" value="${esc(s.staffPhone||'')}"></div><div class="field"><label>Avisar após quantos dias de atraso</label><input id="daysAfter" type="number" min="0" value="${s.daysAfterDue??1}"></div><div class="field"><label>Repetir aviso a cada quantos dias</label><input id="repeatDays" type="number" min="1" value="${s.repeatDays??3}"></div></div><label class="security-note" style="display:flex;justify-content:space-between;align-items:center">Modo de simulação - não envia mensagem externa <input class="switch" id="dryRun" type="checkbox" ${s.dryRun?'checked':''}></label><button class="primary-btn" id="saveNotify" style="margin-top:14px">Salvar configuração</button></div><div class="card"><h3>Regra implementada</h3><div class="metric"><span>Destino</span><b>Equipe da faculdade</b></div><div class="metric"><span>Gatilho</span><b>Mensalidade atrasada</b></div><div class="metric"><span>Canais</span><b>E-mail, SMS, WhatsApp</b></div><div class="metric"><span>Antiduplicidade</span><b>Registro por canal</b></div><div class="divider"></div><div class="alert-box">Para envio real, cadastre as credenciais do SMTP e dos provedores de SMS/WhatsApp no arquivo de ambiente do servidor. As chaves nunca devem ficar no navegador.</div></div><div class="card span-3"><div class="card-head"><h3>Histórico de notificações</h3><span class="badge blue">Últimos registros</span></div>${state.logs.length?state.logs.map(l=>`<div class="log-line"><span>${esc(l.date)}</span><span>${esc(l.channel)}</span><span>${esc(l.student)}</span><span><i class="status-dot ${l.status==='Simulado'?'sim':''}"></i>${esc(l.status)}</span></div>`).join(''):'<div class="empty">Nenhuma notificação registrada.</div>'}</div></div>`}
function adminReports(){const s=adminStats();return `<div class="grid grid-4"><div class="card stat-card"><div class="stat-icon">AL</div><div><div class="label">Alunos</div><div class="value">${state.students.length}</div></div></div><div class="card stat-card green"><div class="stat-icon">TX</div><div><div class="label">Taxa de recebimento</div><div class="value">${s.rate}%</div></div></div><div class="card stat-card red"><div class="stat-icon">IN</div><div><div class="label">Cobranças atrasadas</div><div class="value">${s.overdue}</div></div></div><div class="card stat-card orange"><div class="stat-icon">AC</div><div><div class="label">Acessos suspensos</div><div class="value">${state.students.filter(x=>!x.access).length}</div></div></div></div><div class="grid grid-2" style="margin-top:16px"><div class="card"><h3>Receita mensal</h3><div class="chart">${[58,69,74,82,79,91,86].map((h,i)=>`<div class="bar" style="height:${h}%"><span>${['Fev','Mar','Abr','Mai','Jun','Jul','Ago'][i]}</span></div>`).join('')}</div></div><div class="card"><h3>Indicadores gerenciais</h3><div class="metric"><span>Valor total cobrado</span><b>${money(s.due)}</b></div><div class="metric"><span>Valor pago</span><b>${money(s.paid)}</b></div><div class="metric"><span>Valor em aberto</span><b>${money(s.due-s.paid)}</b></div><div class="metric"><span>Alunos com acesso ativo</span><b>${s.active}</b></div></div></div>`}
function adminAcademic(){return `<div class="grid grid-3"><div class="card"><h3>Turmas</h3><p class="small muted">Estrutura preparada para cadastro de turmas, módulos e períodos.</p><button class="secondary-btn full">Gerenciar turmas</button></div><div class="card"><h3>Notas e frequência</h3><p class="small muted">Professores ou secretaria podem lançar resultados conforme permissão.</p><button class="secondary-btn full">Lançamentos</button></div><div class="card"><h3>Disciplinas</h3><p class="small muted">Controle de matriz curricular e carga horária.</p><button class="secondary-btn full">Gerenciar disciplinas</button></div></div>`}
function adminCommunications(){return `<div class="grid grid-2"><div class="card"><h3>Novo comunicado</h3><div class="field"><label>Título</label><input placeholder="Título do aviso"></div><div class="field"><label>Público</label><select><option>Todos os alunos</option><option>Turma específica</option><option>Curso específico</option></select></div><div class="field"><label>Mensagem</label><textarea rows="6"></textarea></div><button class="primary-btn" onclick="toast('Comunicado publicado em modo demonstrativo.','info')">Publicar</button></div><div class="card"><h3>Comunicados recentes</h3><div class="notice"><h4>Renovação de matrícula</h4><p>Publicado para todos os alunos.</p></div><div class="notice"><h4>Semana de avaliações</h4><p>Publicado para turmas do segundo módulo.</p></div></div></div>`}
function adminAudit(){return `<div class="grid grid-2"><div class="card"><h3>Política de acesso</h3><div class="metric"><span>Portais separados</span><b>Sim</b></div><div class="metric"><span>Senha do aluno visível ao admin</span><b>Não</b></div><div class="metric"><span>Reset por link temporário</span><b>Sim</b></div><div class="metric"><span>Suspensão de acesso</span><b>Sim</b></div><div class="metric"><span>Registro de ações</span><b>Preparado</b></div></div><div class="card"><h3>Princípio de segurança</h3><p class="small muted">Contas administrativas e contas de alunos têm autenticação e autorização separadas. O backend valida o perfil em cada rota sensível. Credenciais de APIs externas ficam somente no servidor.</p><div class="success-box">A estrutura no Cloudflare Workers registra alterações administrativas e não expõe senhas em texto puro.</div></div></div>`}

function attachEvents(){if(portal==='student'){
 if(state.page==='requerimentos')document.getElementById('newReq')?.addEventListener('click',newRequest);
 if(state.page==='perfil')document.getElementById('profileForm')?.addEventListener('submit',async e=>{e.preventDefault();try{const patch={name:document.getElementById('pfName').value,email:document.getElementById('pfEmail').value,phone:document.getElementById('pfPhone').value};state.user=await API.updateStudent(state.user.id,patch);sessionStorage.setItem('mi_user',JSON.stringify(state.user));toast('Dados atualizados.');renderApp()}catch(err){toast(err.message,'error')}});
 if(state.page==='seguranca'){document.getElementById('passwordForm')?.addEventListener('submit',async e=>{e.preventDefault();const n=document.getElementById('newPass').value,c=document.getElementById('confirmPass').value;if(n!==c)return toast('As novas senhas não conferem.','error');try{const r=await API.changeOwnPassword(document.getElementById('currentPass').value,n);toast(r.message);e.target.reset()}catch(err){toast(err.message,'error')}});document.getElementById('selfReset')?.addEventListener('click',async()=>{try{const r=await API.forgot('student',state.user.email);toast(r.message,'info')}catch(e){toast(e.message,'error')}})}
 }else{
 if(state.page==='alunos'){document.getElementById('newStudent')?.addEventListener('click',newStudent);const search=document.getElementById('studentSearch');search?.addEventListener('input',()=>{const q=search.value.toLowerCase();document.getElementById('studentRows').innerHTML=studentRows(state.students.filter(s=>(s.name+s.registration+s.email).toLowerCase().includes(q)))});document.getElementById('onlyBlocked')?.addEventListener('click',()=>document.getElementById('studentRows').innerHTML=studentRows(state.students.filter(s=>!s.access)))}
 if(state.page==='admin-financeiro')document.getElementById('newCharge')?.addEventListener('click',newCharge);
 if(state.page==='notificacoes'){document.getElementById('saveNotify')?.addEventListener('click',saveNotificationSettings);document.getElementById('runCheck')?.addEventListener('click',runOverdueCheck)}
 }}
async function newRequest(){const m=modal(`<div class="modal-head"><h3>Novo requerimento</h3><button class="close-btn">Fechar</button></div><div class="field"><label>Tipo</label><select id="reqType"><option>Declaração de Matrícula</option><option>Revisão de nota</option><option>Aproveitamento de Estudos</option><option>Segunda via de documento</option></select></div><div class="field"><label>Justificativa</label><textarea id="reqText" rows="5"></textarea></div><div class="modal-actions"><button class="secondary-btn cancel">Cancelar</button><button class="primary-btn submit">Enviar</button></div>`);m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.submit').onclick=async()=>{try{await API.createRequest(m.querySelector('#reqType').value,m.querySelector('#reqText').value);state.requests=await API.requests();m.remove();toast('Requerimento protocolado.');renderApp()}catch(e){toast(e.message,'error')}}}
async function newStudent(){const m=modal(`<div class="modal-head"><h3>Cadastrar aluno</h3><button class="close-btn">Fechar</button></div><div class="grid grid-2"><div class="field span-2"><label>Nome completo</label><input id="nsName"></div><div class="field"><label>E-mail do aluno</label><input id="nsEmail" type="email"></div><div class="field"><label>CPF</label><input id="nsCpf"></div><div class="field"><label>Telefone</label><input id="nsPhone"></div><div class="field"><label>Matrícula</label><input id="nsReg"></div><div class="field span-2"><label>Curso</label><input id="nsCourse"></div><div class="field"><label>Mensalidade</label><input id="nsFee" type="number" step="0.01" value="450"></div><div class="field"><label>Período</label><input id="nsPeriod" value="1º Módulo"></div></div><div class="security-note">O administrador não cria a senha do aluno. Após o cadastro, o sistema envia um link de ativação para que o próprio aluno defina a senha.</div><div class="modal-actions"><button class="secondary-btn cancel">Cancelar</button><button class="primary-btn create">Cadastrar e enviar ativação</button></div>`);m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.create').onclick=async()=>{try{const payload={name:m.querySelector('#nsName').value,email:m.querySelector('#nsEmail').value,cpf:m.querySelector('#nsCpf').value,phone:m.querySelector('#nsPhone').value,registration:m.querySelector('#nsReg').value,course:m.querySelector('#nsCourse').value,monthlyFee:Number(m.querySelector('#nsFee').value),period:m.querySelector('#nsPeriod').value,campus:'Unidade Centro'};if(!payload.name||!payload.email||!payload.registration)return toast('Preencha nome, e-mail e matrícula.','error');await API.createStudent(payload);state.students=await API.listStudents();m.remove();toast('Aluno cadastrado. Link de ativação destinado ao próprio aluno.','info');renderApp()}catch(e){toast(e.message,'error')}}}
async function newCharge(){const m=modal(`<div class="modal-head"><h3>Nova cobrança</h3><button class="close-btn">Fechar</button></div><div class="field"><label>Aluno</label><select id="chStudent">${state.students.map(s=>`<option value="${s.id}">${esc(s.name)} - ${s.registration}</option>`).join('')}</select></div><div class="field"><label>Descrição</label><input id="chDesc" value="Mensalidade - Setembro/2026"></div><div class="grid grid-2"><div class="field"><label>Vencimento</label><input id="chDue" type="date" value="2026-09-10"></div><div class="field"><label>Valor</label><input id="chAmount" type="number" step="0.01" value="450"></div></div><div class="modal-actions"><button class="secondary-btn cancel">Cancelar</button><button class="primary-btn create">Gerar cobrança</button></div>`);m.querySelector('.cancel').onclick=()=>m.remove();m.querySelector('.create').onclick=async()=>{try{await API.addCharge(m.querySelector('#chStudent').value,m.querySelector('#chDesc').value,m.querySelector('#chDue').value,m.querySelector('#chAmount').value);state.payments=await API.listPayments();m.remove();toast('Cobrança criada.');renderApp()}catch(e){toast(e.message,'error')}}}
async function saveNotificationSettings(){try{state.settings=await API.saveSettings({email:document.getElementById('chEmail').checked,sms:document.getElementById('chSms').checked,whatsapp:document.getElementById('chWhatsapp').checked,staffEmail:document.getElementById('staffEmail').value.trim(),staffPhone:document.getElementById('staffPhone').value.trim(),daysAfterDue:Number(document.getElementById('daysAfter').value),repeatDays:Number(document.getElementById('repeatDays').value),dryRun:document.getElementById('dryRun').checked});toast('Configuração de notificações salva.');renderApp()}catch(e){toast(e.message,'error')}}
async function runOverdueCheck(){try{const r=await API.checkOverdue();state.logs=await API.logs();toast(`${r.overdue} cobrança(s) atrasada(s); ${r.notifications} notificação(ões) processada(s).`,r.dryRun?'info':'success');renderApp()}catch(e){toast(e.message,'error')}}
function downloadText(name,text){const b=new Blob([text],{type:'text/plain;charset=utf-8'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download=name;a.click();URL.revokeObjectURL(u)}window.downloadText=downloadText;

if(session.user){if((portal==='admin'&&session.user.role!=='Administrador')||(portal==='student'&&session.user.role==='Administrador')){logout()}else boot()}else renderLogin();
